('cdcb62a9-e571-529e-a944-5073a9ebea7a'::uuid,'est2','"Coordinate Geometry, Circles & Conics"'::jsonb,'medium','mcq','"A square 2 feet on a side is cut out of a circle with radius 10 feet as shown in the figure below. Which of the following expressions gives the area of the shaded region, in square feet?\n[Figure: shaded circle of radius 10 with an unshaded 2×2 square hole in its center.]"'::jsonb,'[{"key":"A","text":"π(10 − 2²)"},{"key":"B","text":"π(10 − 2)²"},{"key":"C","text":"π(10 − 1)²"},{"key":"D","text":"π10² − 1²"},{"key":"E","text":"π10² − 2²"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t3.md","source_sha256":"99cce7d4af2c7af699a1cf3d3f0d1ae316a0c60415b3dd761716634dbfe150cd","source_question_id":"T3-43","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Coordinate Geometry, Circles & Conics"}'::jsonb,'"E"'::jsonb,'"Source-keyed answer from book_t3.md (T3-43)."'::jsonb),
