('190c5858-0bab-5d29-805f-dfed5671a8e2'::uuid,'est2','"Statistics, Probability & Data Analysis"'::jsonb,'medium','mcq','"A hat has 20 cards in it. On each card is written the name of one of three people. Mike has twice as many cards with his name than Jane and Jane has 4 more cards than Eric. If a card is pulled out of the hat at random, what is the probability that it has Eric''s name on it?"'::jsonb,'[{"key":"A","text":"1/20"},{"key":"B","text":"1/10"},{"key":"C","text":"1/6"},{"key":"D","text":"1/3"},{"key":"E","text":"1/2"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t4.md","source_sha256":"d5072a8925374ae6d433150b6cc5dc63cd6fcb0e1eaef6c8c4728258e86529f5","source_question_id":"T4-15","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from book_t4.md (T4-15)."'::jsonb),
