('216bd3e6-d766-56a9-bef1-c2463656ede1'::uuid,'est2','"Solid Geometry & Volume"'::jsonb,'medium','mcq','"The figure below shows a cross section of a swimming pool that is 50 feet (ft) wide and 75 ft long. The bottom is horizontal for 25 ft, then slopes up, and the sides are vertical. What is the volume of water, in cubic ft, that is required to fill the pool to a depth, as shown, of 10 ft at the deep end and 4 ft at the shallow end?\n[Figure: cross section — a trapezoidal profile: the first 25 ft of length is at a constant depth of 10 ft; the bottom then slopes up linearly over the remaining 50 ft to a depth of 4 ft.]"'::jsonb,'[{"key":"F","text":"600"},{"key":"G","text":"25,000"},{"key":"H","text":"26,250"},{"key":"J","text":"30,000"},{"key":"K","text":"47,500"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t4.md","source_sha256":"d5072a8925374ae6d433150b6cc5dc63cd6fcb0e1eaef6c8c4728258e86529f5","source_question_id":"T4-39","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Solid Geometry & Volume"}'::jsonb,'"J"'::jsonb,'"Source-keyed answer from book_t4.md (T4-39)."'::jsonb),
